public sealed class DisposableTheoTrigger : SourceTriggerEntityState
{
    private readonly DisposableTheoHooks runtime;

public DisposableTheoTrigger(ISourceEngineContext engine, EntityData data, Vector2 offset)
    : base(((ISourceEntitySourceDataEnvironment)engine).EntitySourceDataRegistration,
        data.Position + offset, data.Width, data.Height,
        ((ISourceExtremaEnvironment)engine).ExtremaArithmetic)
