namespace Celeste.Mods.DisposableTheo.Modules
{
    [RuntimeTypeAlias("Celeste.Mod.DisposableTheo.DisposableTheoModule")]
    public sealed class DisposableTheoModule : SourceEverestModule
    {
        public override Type SettingsType => typeof(DisposableTheoSettings);
        public DisposableTheoSettings Settings => (DisposableTheoSettings)_Settings;
        internal DisposableTheoHooks Runtime { get; private set; }
        internal ISourceEngineContext Engine => SourceEngine;

        public DisposableTheoModule(ISourceEngineContext engine) : base(engine)
        {
        }

        public override void Load()
        {
            Runtime = new DisposableTheoHooks(this);
            Runtime.Load();
        }

        public override void Unload()
        {
            Runtime?.Dispose();
            Runtime = null;
        }

        internal static DisposableTheoModule For(ISourceEngineContext engine)
            => ((ISourceEverestModulesEnvironment)engine).Modules.OfType<DisposableTheoModule>().Single();
    }
}

