namespace Celeste.Mods.DisposableTheo.Runtime
{
    public sealed partial class DisposableTheoHooks : IDisposable
    {
        private readonly DisposableTheoModule module;
        private readonly List<IDisposable> hooks = new();
        internal bool Disposable, CanLeaveBehind;

        internal DisposableTheoHooks(DisposableTheoModule module)
        {
            this.module = module;
        }

        internal void Load()
        {
            try
            {
                hooks.Add(new ILHook(typeof(TheoCrystalState).GetMethod(nameof(TheoCrystalState.Die)), HookTheoDeath));
                hooks.Add(new ILHook(
                    typeof(OriginalLevelSceneRoot).GetMethod(nameof(OriginalLevelSceneRoot.EnforceBounds)),
                    HookBounds));
                hooks.Add(new Hook(
                    typeof(OriginalLevelSceneRoot).GetMethod(nameof(OriginalLevelSceneRoot.TransitionTo)),
                    (Action<Action<OriginalLevelSceneRoot, OriginalLevelRoomData, Vector2>, OriginalLevelSceneRoot,
                        OriginalLevelRoomData, Vector2>)Transition));
                // PlayerWorld's genuine Throw consumer calls this controller directly.
                hooks.Add(new Hook(typeof(PlayerHoldingController).GetMethod(nameof(PlayerHoldingController.Throw)),
                    (Action<Action<PlayerHoldingController>, PlayerHoldingController>)Throw));
            }
            catch
            {
                Dispose();
                throw;
            }
        }

        public void Dispose()
        {
            for (int i = hooks.Count - 1; i >= 0; i--) hooks[i].Dispose();
            hooks.Clear();
            Disposable = CanLeaveBehind = false;
        }

        private bool Owns(object scene) => scene is ISourceEngineContextScene owner &&
                                           ReferenceEquals(owner.EngineContext, module.Engine);

        private void HookTheoDeath(ILContext il)
        {
            var cursor = new ILCursor(il);
            bool found = false;
            while (cursor.TryGotoNext(MoveType.After, instruction => instruction.OpCode == OpCodes.Callvirt &&
                                                                     instruction.Operand is GenericInstanceMethod
                                                                         method && method.Name == "GetTrackedEntity" &&
                                                                     method.GenericArguments.Count == 1 &&
                                                                     method.GenericArguments[0].FullName ==
                                                                     typeof(RoomPlayerSession).FullName))
            {
                found = true;
                cursor.Emit(OpCodes.Ldarg_0);
                cursor.EmitDelegate<Func<RoomPlayerSession, TheoCrystalState, RoomPlayerSession>>((player, theo) =>
                    Owns(theo.Scene) ? (

);
            }

            if (!found) throw new InvalidOperationException("TheoCrystal.Die player lookup was not found.");
        }

        private void HookBounds(ILContext il)
        {
            var cursor = new ILCursor(il);
            bool found = false;
            while (cursor.TryGotoNext(MoveType.After, instruction => instruction.MatchIsinst(typeof(TheoCrystalState))))
            {
                found = true;
                cursor.Emit(OpCodes.Ldarg_0);
                cursor.EmitDelegate<Func<TheoCrystalState, OriginalLevelSceneRoot, TheoCrystalState>>((theo, level) =>
                    Owns(level) ? (

);
            }

            if (!found) throw new InvalidOperationException("Level.EnforceBounds Theo lookup was not found.");
        }

private void Transition(Action<OriginalLevelSceneRoot, OriginalLevelRoomData, Vector2> orig,
    OriginalLevelSceneRoot level, OriginalLevelRoomData next, Vector2 direction)
{
    if (!Owns(level))
    {
        orig(level, next, direction);
        return;
    }

        }

        private static RoomPlayerSession GetPlayer(OriginalLevelSceneRoot level)
            => level.SourceScene.Entities.GetTrackedEntity<RoomPlayerSession>(typeof(RoomPlayerSession).FullName);

        private static IEnumerable<TheoCrystalState> GetTheos(OriginalLevelSceneRoot level)
        {
            foreach (TheoCrystalState theo in level.SourceScene.Entities.GetTrackedEntities("Celeste.TheoCrystal"))
                yield return theo;
        }

        private void RemoveTransitionTag(TheoCrystalState theo)
        {
            int tag = ((ISourcePersistentTransitionExecutionTagsEnvironment)module.Engine)
                .PersistentTransitionExecutionTags.TransitionUpdate.Value;
            theo.Tags &= ~tag;
        }
    }
}
